#! bin/bash

# This script moves the STARLog files generated by STAR into a separate sub-directory for clarity.

#Path to STAR data folder
star_path=../05_STAR_alignments/

#Path to raw data folder containing the fastq.gz and fastq.gz.md5 files I downloaded from Genewiz.
log_files_list=$star_path*_STARLog.*
readspergene_list=$star_path"*_STARReadsPerGene.out.tab"
starsj_list=$star_path"*_STARSJ.out.tab"

#Path to STAR log directory
log_path=$star_path"STAR_logs/"
readspergene_path=$star_path"STAR_ReadsPerGene/"
starsj_path=$star_path"STAR_STARsj/"

#Checks if output STAR_log directory exists and if not, makes one.
if [ ! -d "$log_path" ]; then
    echo $log_path does not exist! Creating one now.
    mkdir $log_path
fi

#Checks if output STAR_ReadsPerGene directory exists and if not, makes one.
if [ ! -d "$readspergene_path" ]; then
    echo $readspergene_path does not exist! Creating one now.
    mkdir $readspergene_path
fi

#Checks if output STAR_STARsj directory exists and if not, makes one.
if [ ! -d "$starsj_path" ]; then
    echo $starsj_path does not exist! Creating one now.
    mkdir $starsj_path
fi

mv -n $log_files_list $log_path
mv -n $readspergene_list $readspergene_path
mv -n $starsj_list $starsj_path
